<template>
  <view class="search-container">
    <!-- 顶部轮播图 -->
    <swiper class="swiper" indicator-dots autoplay circular interval="3000">
      <swiper-item v-for="(item, index) in banners" :key="index">
        <image :src="item.image" mode="aspectFill" class="swiper-image" @click="navigateToDetail(item)"></image>
      </swiper-item>
    </swiper>

    <!-- 搜索框 -->
    <view class="search-bar">
      <input class="search-input" placeholder="搜索景点、店铺或美食" v-model="searchKeyword" @input="handleSearchInput"
        confirm-type="search" @confirm="handleSearch" />
      <uni-icons type="search" size="20" color="#00B4D8" @click="handleSearch"></uni-icons>
    </view>

    <!-- 热门搜索 -->
    <view class="hot-search" v-if="!searchResults && !historyKeywords.length">
      <view class="section-title">热门搜索</view>
      <view class="hot-tags">
        <text class="hot-tag" v-for="(tag, index) in hotKeywords" :key="index" @click="searchByTag(tag)">{{tag}}</text>
      </view>
    </view>

    <!-- 历史搜索 -->
    <view class="history-search" v-if="!searchResults && historyKeywords.length">
      <view class="section-header">
        <view class="section-title">历史搜索</view>
        <text class="clear-btn" @click="clearHistory">清空</text>
      </view>
      <view class="history-tags">
        <view class="history-tag" v-for="(item, index) in historyKeywords" :key="index" @click="searchByTag(item)">
          <text>{{item}}</text>
          <text class="iconfont icon-close" @click.stop="removeHistoryItem(index)"></text>
        </view>
      </view>
    </view>

    <!-- 搜索结果 -->
    <view class="search-results" v-if="searchResults">
      <!-- 搜索结果分类 -->
      <view class="result-tabs">
        <text class="result-tab" :class="{active: activeTab === 'spot'}" @click="switchTab('spot')">景点</text>
        <text class="result-tab" :class="{active: activeTab === 'shop'}" @click="switchTab('shop')">店铺</text>
        <text class="result-tab" :class="{active: activeTab === 'food'}" @click="switchTab('food')">美食</text>
      </view>

      <!-- 景点结果 -->
      <view class="result-list" v-if="activeTab === 'spot' && spotResults.length">
        <view class="result-item" v-for="item in spotResults" :key="item.id" @click="navigateToSpotDetail(item.id)">
          <image class="result-image" :src="item.image" mode="aspectFill"></image>
          <view class="result-info">
            <text class="result-title">{{item.name}}</text>
            <view class="result-rating">
              <text class="iconfont icon-star"></text>
              <text>{{item.rating}}</text>
            </view>
            <text class="result-address">{{item.address}}</text>
          </view>
        </view>
      </view>

      <!-- 店铺结果 -->
      <view class="result-list" v-if="activeTab === 'shop' && shopResults.length">
        <view class="result-item" v-for="item in shopResults" :key="item.id" @click="navigateToShopDetail(item.id)">
          <image class="result-image" :src="item.image" mode="aspectFill"></image>
          <view class="result-info">
            <text class="result-title">{{item.name}}</text>
            <text class="result-type">{{item.type}}</text>
            <text class="result-price">{{item.price}}</text>
          </view>
        </view>
      </view>

      <!-- 美食结果 -->
      <view class="result-list" v-if="activeTab === 'food' && foodResults.length">
        <view class="result-item" v-for="item in foodResults" :key="item.id" @click="navigateToFoodDetail(item.id)">
          <image class="result-image" :src="item.image" mode="aspectFill"></image>
          <view class="result-info">
            <text class="result-title">{{item.title}}</text>
            <text class="result-desc">{{item.desc}}</text>
          </view>
        </view>
      </view>

      <!-- 无结果提示 -->
      <view class="no-result" v-if="hasNoResult">
        <image class="no-result-image" src="/static/no-result.png"></image>
        <text class="no-result-text">没有找到相关结果</text>
        <text class="no-result-tip">换个关键词试试吧</text>
      </view>
    </view>
  </view>
</template>

<script>
  import {
    scenicSpotApi,
    shopApi,
    foodApi,
    imageApi,
    searchApi
  } from '@/api';
  import uniIcons from '@dcloudio/uni-ui/lib/uni-icons/uni-icons.vue'
  export default {
    components: {
      uniIcons
    },
    data() {
      return {
        banners: [{
            image: 'https://vcg04.cfp.cn/creative/vcg/800/new/VCG211334501581.jpg',
            type: 'spot',
            id: 1
          },
          {
            image: 'https://sns-webpic-qc.xhscdn.com/202505271433/97fefcf0e8f631fbae93585e95efc085/1040g2sg31e27vq4t0s9g48sa21548r2lgi1l678!nd_dft_wgth_webp_3',
            type: 'shop',
            id: 2
          },
          {
            image: 'https://sns-webpic-qc.xhscdn.com/202505271434/ffc0cab9d70a3a907feae4f7a954747c/1040g008315uutpb0gk605o9tdvvgkj371p24g4g!nd_dft_wlteh_webp_3',
            type: 'food',
            id: 1
          }
        ],
        spots: [],
        shops: [],
        foods: [],
        searchKeyword: '',
        searchTimer: null
      }
    },
    computed: {
      hasNoResult() {
        return this.searchResults &&
          ((this.activeTab === 'spot' && !this.spotResults.length) ||
            (this.activeTab === 'shop' && !this.shopResults.length) ||
            (this.activeTab === 'food' && !this.foodResults.length))
      }
    },
    onLoad(options) {
      if (options.keyword) {
        this.keyword = decodeURIComponent(options.keyword);
        this.doSearch();
      }
      this.loadHistory();
    },
    methods: {
      handleSearchInput(e) {
        this.searchKeyword = e.detail.value;
        // 防抖处理，300ms后自动搜索
        if (this.searchTimer) {
          clearTimeout(this.searchTimer);
        }
        this.searchTimer = setTimeout(() => {
          if (this.searchKeyword.trim()) {
            this.performSearch();
          }
        }, 300);
      },

      // 处理搜索按钮点击或回车
      handleSearch() {
        if (this.searchKeyword.trim()) {
          this.performSearch();
        } else {
          uni.showToast({
            title: '请输入搜索内容',
            icon: 'none'
          });
        }
      },

      // 执行搜索
      async performSearch() {
        try {
          // 调用通用搜索API
          const res = await searchApi.search(this.searchKeyword, 'all');

          // 跳转到搜索结果页，并传递搜索结果
          uni.navigateTo({
            url: `/pages/search/result?keyword=${encodeURIComponent(this.searchKeyword)}`,
            success: (res) => {
              res.eventChannel.emit('acceptSearchData', {
                keyword: this.searchKeyword,
                results: res.data
              });
            }
          });

        } catch (error) {
          console.error('搜索失败:', error);
          uni.showToast({
            title: '搜索失败，请重试',
            icon: 'none'
          });
        }
      },
      doSearch() {
        if (!this.keyword.trim()) {
          uni.showToast({
            title: '请输入搜索内容',
            icon: 'none'
          });
          return;
        }

        // 模拟搜索数据 - 实际项目中应该调用API
        this.spotResults = this.mockSpotResults();
        this.shopResults = this.mockShopResults();
        this.foodResults = this.mockFoodResults();

        this.searchResults = true;
        this.saveToHistory();
      },

      mockSpotResults() {
        // 模拟景点搜索结果
        const allSpots = [{
            id: 1,
            name: '景德镇古窑民俗博览区',
            image: '/static/spot1.jpg',
            rating: 4.8,
            address: '昌江区瓷都大道古窑路1号'
          },
          {
            id: 2,
            name: '中国陶瓷博物馆',
            image: '/static/spot2.jpg',
            rating: 4.7,
            address: '昌江区紫晶北路1号'
          }
        ];

        return allSpots.filter(item =>
          item.name.includes(this.keyword) ||
          item.address.includes(this.keyword)
        );
      },

      mockShopResults() {
        // 模拟店铺搜索结果
        const allShops = [{
            id: 1,
            name: '传统拉坯体验馆',
            image: '/static/shop1.jpg',
            type: '拉坯体验',
            price: '¥80-150',
            rating: 4.9
          },
          {
            id: 2,
            name: '青花绘画工作室',
            image: '/static/shop2.jpg',
            type: '绘画体验',
            price: '¥120-200',
            rating: 4.8
          }
        ];

        return allShops.filter(item =>
          item.name.includes(this.keyword) ||
          item.type.includes(this.keyword)
        );
      },

      mockFoodResults() {
        // 模拟美食搜索结果
        const allFoods = [{
          id: 1,
          title: '景德镇特色美食',
          desc: '探索景德镇独特的地方美食文化与传统',
          image: '/static/food1.jpg'
        }];

        return allFoods.filter(item =>
          item.title.includes(this.keyword) ||
          item.desc.includes(this.keyword)
        );
      },

      switchTab(tab) {
        this.activeTab = tab;
      },

      searchByTag(tag) {
        this.keyword = tag;
        this.doSearch();
      },

      clearSearch() {
        this.keyword = '';
        this.searchResults = false;
      },

      goBack() {
        uni.navigateBack();
      },

      loadHistory() {
        try {
          const history = uni.getStorageSync('searchHistory') || [];
          this.historyKeywords = history;
        } catch (e) {
          console.error('加载搜索历史失败', e);
        }
      },

      saveToHistory() {
        if (!this.keyword.trim()) return;

        // 去重
        const index = this.historyKeywords.indexOf(this.keyword);
        if (index !== -1) {
          this.historyKeywords.splice(index, 1);
        }

        // 添加到开头
        this.historyKeywords.unshift(this.keyword);

        // 限制数量
        if (this.historyKeywords.length > 10) {
          this.historyKeywords = this.historyKeywords.slice(0, 10);
        }

        try {
          uni.setStorageSync('searchHistory', this.historyKeywords);
        } catch (e) {
          console.error('保存搜索历史失败', e);
        }
      },

      removeHistoryItem(index) {
        this.historyKeywords.splice(index, 1);
        try {
          uni.setStorageSync('searchHistory', this.historyKeywords);
        } catch (e) {
          console.error('删除搜索历史失败', e);
        }
      },

      clearHistory() {
        this.historyKeywords = [];
        try {
          uni.removeStorageSync('searchHistory');
        } catch (e) {
          console.error('清空搜索历史失败', e);
        }
      },

      navigateToSpotDetail(id) {
        uni.navigateTo({
          url: `/pages/spot/detail?id=${id}`
        });
      },

      navigateToShopDetail(id) {
        uni.navigateTo({
          url: `/pages/shop/detail?id=${id}`
        });
      },

      navigateToFoodDetail(id) {
        uni.navigateTo({
          url: `/pages/food/detail?id=${id}`
        });
      }
    }
  }
</script>

<style>
  .search-container {
    padding: 20rpx 30rpx;
    background-color: #f5f5f5;
    min-height: 100vh;
  }

  .search-bar {
    display: flex;
    align-items: center;
    margin-bottom: 30rpx;
  }

  .search-input-container {
    flex: 1;
    display: flex;
    align-items: center;
    background-color: #fff;
    border-radius: 50rpx;
    padding: 15rpx 30rpx;
    margin-right: 20rpx;
  }

  .search-input {
    flex: 1;
    font-size: 28rpx;
    color: #333;
    margin-left: 15rpx;
  }

  .icon-search {
    color: #999;
    font-size: 32rpx;
  }

  .icon-close {
    color: #999;
    font-size: 32rpx;
    padding: 10rpx;
  }

  .cancel-btn {
    font-size: 28rpx;
    color: #666;
  }

  .section-title {
    font-size: 28rpx;
    color: #999;
    margin-bottom: 20rpx;
  }

  .hot-tags {
    display: flex;
    flex-wrap: wrap;
  }

  .hot-tag {
    background-color: #fff;
    border-radius: 30rpx;
    padding: 10rpx 25rpx;
    margin-right: 20rpx;
    margin-bottom: 20rpx;
    font-size: 26rpx;
    color: #333;
  }

  .section-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 20rpx;
  }

  .clear-btn {
    font-size: 26rpx;
    color: #999;
  }

  .history-tags {
    display: flex;
    flex-wrap: wrap;
  }

  .history-tag {
    display: flex;
    align-items: center;
    background-color: #fff;
    border-radius: 30rpx;
    padding: 10rpx 25rpx;
    margin-right: 20rpx;
    margin-bottom: 20rpx;
    font-size: 26rpx;
    color: #333;
  }

  .history-tag .icon-close {
    margin-left: 10rpx;
    font-size: 24rpx;
  }

  .result-tabs {
    display: flex;
    border-bottom: 1rpx solid #eee;
    margin-bottom: 30rpx;
  }

  .result-tab {
    flex: 1;
    text-align: center;
    padding: 20rpx 0;
    font-size: 28rpx;
    color: #666;
    position: relative;
  }

  .result-tab.active {
    color: #00B4D8;
    font-weight: bold;
  }

  .result-tab.active:after {
    content: '';
    position: absolute;
    bottom: 0;
    left: 50%;
    transform: translateX(-50%);
    width: 80rpx;
    height: 4rpx;
    background-color: #00B4D8;
    border-radius: 2rpx;
  }

  .result-item {
    display: flex;
    background-color: #fff;
    border-radius: 12rpx;
    margin-bottom: 20rpx;
    padding: 20rpx;
  }

  .result-image {
    width: 180rpx;
    height: 180rpx;
    border-radius: 8rpx;
  }

  .result-info {
    flex: 1;
    margin-left: 20rpx;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
  }

  .result-title {
    font-size: 28rpx;
    color: #333;
    font-weight: bold;
  }

  .result-rating {
    display: flex;
    align-items: center;
    font-size: 24rpx;
    color: #ffb400;
  }

  .result-rating .iconfont {
    margin-right: 5rpx;
  }

  .result-address {
    font-size: 24rpx;
    color: #999;
  }

  .result-type {
    font-size: 24rpx;
    color: #00B4D8;
    background-color: rgba(0, 180, 216, 0.1);
    padding: 4rpx 12rpx;
    border-radius: 20rpx;
    align-self: flex-start;
  }

  .result-price {
    font-size: 26rpx;
    color: #ff6b6b;
  }

  .result-desc {
    font-size: 24rpx;
    color: #999;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
  }

  .no-result {
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 100rpx 0;
  }

  .no-result-image {
    width: 200rpx;
    height: 200rpx;
    margin-bottom: 30rpx;
  }

  .no-result-text {
    font-size: 28rpx;
    color: #666;
    margin-bottom: 15rpx;
  }

  .no-result-tip {
    font-size: 24rpx;
    color: #999;
  }

  .icon-close:before {
    content: "\e601";
  }
</style>